package io.github.ningpp.compat;

import java.util.Arrays;

/**
 * Lightweight read-only array-slice container (generated by CSharpToJava converter).
 * Does not simulate C# ref-struct lifetime semantics.
 */
public final class ReadOnlySpan<T> {
    private final Object array;
    private String stringBacking;
    private int offset;
    private int length;

    /** Default (empty) span — mirrors default(ReadOnlySpan&lt;T&gt;). */
    public ReadOnlySpan() {
        this.array = null;
        this.stringBacking = null;
        this.offset = 0;
        this.length = 0;
    }

    /** Mirrors ReadOnlySpan&lt;T&gt;.Empty. */
    @SuppressWarnings("rawtypes")
    public static final ReadOnlySpan Empty = new ReadOnlySpan<>();

    /** Mirrors ReadOnlySpan&lt;T&gt;.Empty as a static method call (generated getter form).
     *  Raw return type keeps casts like (ReadOnlySpan&lt;Integer&gt;) ReadOnlySpan.getEmpty()
     *  compilable — Java does not use the cast target type for generic method inference. */
    @SuppressWarnings({ "rawtypes", "unchecked" })
    public static ReadOnlySpan getEmpty() {
        return Empty;
    }

    public ReadOnlySpan(T[] array) {
        this.array = array;
        this.stringBacking = null;
        this.offset = 0;
        this.length = array == null ? 0 : array.length;
    }

    /** Primitive byte[] backing — mirrors C# byte[] → ReadOnlySpan&lt;byte&gt;. */
    public ReadOnlySpan(byte[] array) {
        this.array = array;
        this.stringBacking = null;
        this.offset = 0;
        this.length = array == null ? 0 : array.length;
    }

    /** Primitive char[] backing — mirrors C# char[] → ReadOnlySpan&lt;char&gt;. */
    public ReadOnlySpan(char[] array) {
        this.array = array;
        this.stringBacking = null;
        this.offset = 0;
        this.length = array == null ? 0 : array.length;
    }

    /** Copy constructor — allows wrapping an existing ReadOnlySpan without type inference issues */
    public ReadOnlySpan(ReadOnlySpan<T> other) {
        this.array = other.array;
        this.stringBacking = other.stringBacking;
        this.offset = other.offset;
        this.length = other.length;
    }

    public ReadOnlySpan(T[] array, int offset, int length) {
        if (array == null) {
            if (offset != 0 || length != 0) {
                throw new IndexOutOfBoundsException(
                    "offset=" + offset + ", length=" + length + ", arrayLength=null");
            }
            this.array = null;
            this.stringBacking = null;
            this.offset = 0;
            this.length = 0;
            return;
        }
        if (offset < 0 || length < 0 || offset + length > array.length) {
            throw new IndexOutOfBoundsException(
                "offset=" + offset + ", length=" + length + ", arrayLength=" + array.length);
        }
        this.array = array;
        this.stringBacking = null;
        this.offset = offset;
        this.length = length;
    }

    /** Primitive byte[] slice backing — mirrors C# byte[] → ReadOnlySpan&lt;byte&gt;. */
    public ReadOnlySpan(byte[] array, int offset, int length) {
        if (array == null) {
            if (offset != 0 || length != 0) {
                throw new IndexOutOfBoundsException(
                    "offset=" + offset + ", length=" + length + ", arrayLength=null");
            }
            this.array = null;
            this.stringBacking = null;
            this.offset = 0;
            this.length = 0;
            return;
        }
        if (offset < 0 || length < 0 || offset + length > array.length) {
            throw new IndexOutOfBoundsException(
                "offset=" + offset + ", length=" + length + ", arrayLength=" + array.length);
        }
        this.array = array;
        this.stringBacking = null;
        this.offset = offset;
        this.length = length;
    }

    /** Primitive char[] slice backing — mirrors C# char[] → ReadOnlySpan&lt;char&gt;. */
    public ReadOnlySpan(char[] array, int offset, int length) {
        if (array == null) {
            if (offset != 0 || length != 0) {
                throw new IndexOutOfBoundsException(
                    "offset=" + offset + ", length=" + length + ", arrayLength=null");
            }
            this.array = null;
            this.stringBacking = null;
            this.offset = 0;
            this.length = 0;
            return;
        }
        if (offset < 0 || length < 0 || offset + length > array.length) {
            throw new IndexOutOfBoundsException(
                "offset=" + offset + ", length=" + length + ", arrayLength=" + array.length);
        }
        this.array = array;
        this.stringBacking = null;
        this.offset = offset;
        this.length = length;
    }

    public ReadOnlySpan(Span<T> span) {
        this.array = span.getArray();
        this.stringBacking = null;
        this.offset = span.getOffset();
        this.length = span.length();
    }

    /**
     * Creates a lazy, String-backed span. No char array is copied: each get(i)
     * reads directly from the String (and boxes the single char), mirroring C#
     * string.AsSpan() which views the string in place. Without this, every
     * asSpan call materialized the whole substring as a boxed Character[] —
     * e.g. RegexInterpreter.findFirstChar called asSpan on the remaining input
     * on every match attempt, allocating ~1 MB of boxed chars per call.
     */
    public static ReadOnlySpan<Character> fromString(String s, int start, int length) {
        if (start < 0 || length < 0 || start + length > s.length()) {
            throw new IndexOutOfBoundsException(
                "start=" + start + ", length=" + length + ", stringLength=" + s.length());
        }
        ReadOnlySpan<Character> span = new ReadOnlySpan<>(new Character[0]);
        span.stringBacking = s;
        span.offset = start;
        span.length = length;
        return span;
    }

    public int length() {
        return length;
    }

    /** Alias for length() — matches C# Span.Length property getter translation */
    public int getLength() {
        return length;
    }

    /** Mirrors C# Span.IsEmpty. */
    public boolean isEmpty() {
        return length == 0;
    }

    /** Alias for isEmpty() — matches C# IsEmpty property getter translation. */
    public boolean getIsEmpty() {
        return length == 0;
    }

    /** Mirrors C# Span.Clear() — zeroes the span contents. */
    public void clear() {
        for (int i = 0; i < length; i++) {
            if (stringBacking != null) {
                @SuppressWarnings("unchecked")
                T value = (T) java.lang.Character.valueOf('\0');
                setInternal(i, value);
            } else if (array instanceof byte[] bytes) {
                bytes[offset + i] = 0;
            } else if (array instanceof char[] chars) {
                chars[offset + i] = '\0';
            } else if (array instanceof Object[] objects) {
                objects[offset + i] = null;
            }
        }
    }

    /** Element write — supports code that treats this span as writable (C# Span migration). */
    public void set(int index, T value) {
        if (index < 0 || index >= length) {
            throw new IndexOutOfBoundsException("index=" + index + ", length=" + length);
        }
        if (stringBacking != null) {
            setInternal(index, value);
            return;
        }
        if (array instanceof byte[] bytes) {
            bytes[offset + index] = ((Number) value).byteValue();
        } else if (array instanceof char[] chars) {
            chars[offset + index] = ((Character) value).charValue();
        } else {
            @SuppressWarnings("unchecked")
            T[] arr = (T[]) array;
            arr[offset + index] = value;
        }
    }

    @SuppressWarnings("unchecked")
    private void setInternal(int index, T value) {
        if (stringBacking != null) {
            StringBuilder sb = new StringBuilder(stringBacking);
            sb.setCharAt(offset + index, (char) value);
            stringBacking = sb.toString();
            return;
        }
        ((T[]) array)[offset + index] = value;
    }

    public T get(int index) {
        if (index < 0 || index >= length) {
            throw new IndexOutOfBoundsException("index=" + index + ", length=" + length);
        }
        if (stringBacking != null) {
            @SuppressWarnings("unchecked")
            T value = (T) java.lang.Character.valueOf(stringBacking.charAt(offset + index));
            return value;
        }
        if (array instanceof byte[] bytes) {
            @SuppressWarnings("unchecked")
            T value = (T) java.lang.Integer.valueOf(bytes[offset + index] & 0xFF);
            return value;
        }
        if (array instanceof char[] chars) {
            @SuppressWarnings("unchecked")
            T value = (T) java.lang.Character.valueOf(chars[offset + index]);
            return value;
        }
        @SuppressWarnings("unchecked")
        T value = ((T[]) array)[offset + index];
        return value;
    }

    Object getArray() {
        return array;
    }

    /**
     * Package-private: the {@link String} this span views, or {@code null} when it is
     * array-backed. Lets {@link MemoryExtensions} compare in place instead of going
     * through {@link #get(int)}, which boxes one {@link Character} per element.
     */
    String getStringBacking() {
        return stringBacking;
    }

    int getOffset() {
        return offset;
    }

    public ReadOnlySpan<T> slice(int start) {
        return slice(start, length - start);
    }

    public ReadOnlySpan<T> slice(int start, int len) {
        if (start < 0 || len < 0 || start + len > length) {
            throw new IndexOutOfBoundsException(
                "start=" + start + ", len=" + len + ", length=" + length);
        }
        if (stringBacking != null) {
            return (ReadOnlySpan<T>) (ReadOnlySpan<?>) fromString(stringBacking, offset + start, len);
        }
        if (array instanceof byte[] bytes) {
            // Keep the slice as a view over the original byte[] (C# Slice is O(1)).
            // Materializing an Integer[] here makes repeated slicing of a large
            // byte span quadratic (e.g. Utf8JsonReader.consumeComment).
            return new ReadOnlySpan<>(bytes, offset + start, len);
        }
        if (array instanceof char[] chars) {
            // Keep the slice as a view over the original char[] (C# Slice is O(1)).
            return new ReadOnlySpan<>(chars, offset + start, len);
        }
        return new ReadOnlySpan<>((T[]) array, offset + start, len);
    }

    public T[] toArray() {
        if (stringBacking != null) {
            @SuppressWarnings("unchecked")
            T[] copy = (T[]) new Character[length];
            for (int i = 0; i < length; i++) {
                copy[i] = (T) java.lang.Character.valueOf(stringBacking.charAt(offset + i));
            }
            return copy;
        }
        if (array instanceof byte[] bytes) {
            return (T[]) toIntegerArray(bytes, offset, length);
        }
        if (array instanceof char[] chars) {
            Character[] copy = new Character[length];
            for (int i = 0; i < length; i++) {
                copy[i] = chars[offset + i];
            }
            return (T[]) copy;
        }
        return Arrays.copyOfRange((T[]) array, offset, offset + length);
    }

    /**
     * Materializes the slice as a primitive byte[] (elements narrowed from the
     * boxed representation). Used to pin a byte span for MemorySegment.ofArray.
     */
    public byte[] toByteArray() {
        if (array instanceof byte[] bytes) {
            return Arrays.copyOfRange(bytes, offset, offset + length);
        }
        byte[] result = new byte[length];
        for (int i = 0; i < length; i++) {
            Number value = (Number) get(i);
            result[i] = (byte)((value == null ? 0 : value.intValue()) & 0xFF);
        }
        return result;
    }

    /** Materializes the slice as a primitive char[]. Used for MemorySegment.ofArray. */
    public char[] toCharArray() {
        char[] result = new char[length];
        for (int i = 0; i < length; i++) {
            result[i] = (char)((Character) get(i)).charValue();
        }
        return result;
    }

    /**
     * Rebuilds a ReadOnlySpan&lt;Integer&gt; (the converter's byte-span shape) from a
     * pinned MemorySegment, mirroring C# new ReadOnlySpan&lt;byte&gt;((byte*)ptr, length).
     */
    public static ReadOnlySpan<Integer> fromByteSegment(java.lang.foreign.MemorySegment segment, int length) {
        Integer[] data = new Integer[length];
        for (int i = 0; i < length; i++) {
            data[i] = segment.get(java.lang.foreign.ValueLayout.JAVA_BYTE, i) & 0xFF;
        }
        return new ReadOnlySpan<>(data);
    }

    /** Mirrors new ReadOnlySpan&lt;char&gt;((char*)ptr, length) — reads UTF-16 char elements. */
    public static ReadOnlySpan<Character> fromCharSegment(java.lang.foreign.MemorySegment segment, int length) {
        Character[] data = new Character[length];
        for (int i = 0; i < length; i++) {
            data[i] = segment.get(java.lang.foreign.ValueLayout.JAVA_CHAR, (long) i * 2);
        }
        return new ReadOnlySpan<>(data);
    }

    public void copyTo(Span<T> destination) {
        int copyLength = Math.min(length, destination.length());
        for (int i = 0; i < copyLength; i++) {
            destination.set(i, get(i));
        }
    }

    /** C# ReadOnlySpan&lt;T&gt;.CopyTo(Span&lt;T&gt;) overload for char[] destinations. */
    public void copyTo(char[] destination) {
        copyTo(new Span<>(destination));
    }

    /** C# ReadOnlySpan&lt;T&gt;.Fill(T) — sets every element to the given value. */
    public void fill(T value) {
        for (int i = 0; i < length; i++) {
            set(i, value);
        }
    }

    @Override
    public String toString() {
        if (stringBacking != null) {
            return stringBacking.substring(offset, offset + length);
        }
        if (array instanceof Character[] chars) {
            StringBuilder sb = new StringBuilder(length);
            for (int i = 0; i < length; i++) {
                sb.append(chars[offset + i]);
            }
            return sb.toString();
        }
        if (array instanceof char[] chars) {
            return new String(chars, offset, length);
        }
        return super.toString();
    }

    private static Integer[] toIntegerArray(byte[] bytes, int offset, int length) {
        Integer[] copy = new Integer[length];
        for (int i = 0; i < length; i++) {
            copy[i] = bytes[offset + i] & 0xFF;
        }
        return copy;
    }
}
